def choose_move(observation):
    def is_num(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool)

    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def to_point(v):
        if v is None:
            return None
        if isinstance(v, dict):
            for kx, ky in (("x", "y"), ("row", "col"), ("r", "c"), ("i", "j")):
                if kx in v and ky in v and is_num(v.get(kx)) and is_num(v.get(ky)):
                    return [int(v.get(kx)), int(v.get(ky))]
            vals = list(v.values())
            if len(vals) >= 2 and is_num(vals[0]) and is_num(vals[1]):
                return [int(vals[0]), int(vals[1])]
            return None
        if isinstance(v, (list, tuple)):
            if len(v) >= 2 and is_num(v[0]) and is_num(v[1]):
                return [int(v[0]), int(v[1])]
            return None
        return None

    def extract_points(obj):
        pts = []
        if obj is None:
            return pts
        p = to_point(obj)
        if p is not None:
            pts.append(p)
            return pts
        if isinstance(obj, dict):
            for k in ("positions", "points", "locations", "coords", "cells", "tiles", "targets"):
                if k in obj:
                    pts.extend(extract_points(obj.get(k)))
            for v in obj.values():
                pts.extend(extract_points(v))
        elif isinstance(obj, (list, tuple)):
            for item in obj:
                pts.extend(extract_points(item))
        return pts

    def get_self_pos(obs):
        for k in ("self", "agent", "me", "position", "pos", "location", "loc", "my_pos", "self_pos"):
            p = to_point(obs.get(k))
            if p is not None:
                return p
        for k in ("agents", "players", "units"):
            v = obs.get(k)
            if isinstance(v, (list, tuple)) and v:
                first = v[0]
                if isinstance(first, dict):
                    for kk in ("self", "me", "position", "pos", "location"):
                        p = to_point(first.get(kk))
                        if p is not None:
                            return p
                p = to_point(first)
                if p is not None:
                    return p
        return [0, 0]

    def nearest_point(origin, points):
        best = None
        best_d = None
        for p in points:
            d = manhattan(origin, p)
            if best is None or d < best_d:
                best = p
                best_d = d
        return best, best_d

    def get_list_points(keys):
        pts = []
        for k in keys:
            pts.extend(extract_points(observation.get(k)))
        return pts

    me = get_self_pos(observation)

    resources = get_list_points(("resources", "resource", "resource_positions", "food", "items", "collectibles", "targets"))
    enemies = get_list_points(("enemies", "opponents", "enemy_positions", "enemy", "others", "adversaries", "predators"))
    allies = get_list_points(("allies", "teammates", "friends", "team", "ally_positions"))

    # Optional role detection
    role = observation.get("role", observation.get("mode", observation.get("type", "")))
    role = str(role).lower() if role is not None else ""

    # Threat avoidance: if an enemy is adjacent, move away.
    nearest_enemy, ed = nearest_point(me, enemies)
    if nearest_enemy is not None and ed is not None and ed <= 2:
        dx = clamp_step(me[0] - nearest_enemy[0])
        dy = clamp_step(me[1] - nearest_enemy[1])
        if dx == 0 and dy == 0:
            dx = 1
        return [dx, dy]

    # Pursuit: if role hints at pursuit, chase nearest enemy/target.
    if "purs" in role or "hunt" in role or "pred" in role:
        target, _ = nearest_point(me, enemies)
        if target is not None:
            return [clamp_step(target[0] - me[0]), clamp_step(target[1] - me[1])]

    # Resource collection / expansion: prefer resources, then neutral/frontier-like cells.
    target, _ = nearest_point(me, resources)
    if target is not None:
        return [clamp_step(target[0] - me[0]), clamp_step(target[1] - me[1])]

    # Territory control: if grid/board available, move toward center or frontier.
    grid = observation.get("grid", observation.get("board", observation.get("map", None)))
    if isinstance(grid, (list, tuple)) and grid:
        h = len(grid)
        w = len(grid[0]) if isinstance(grid[0], (list, tuple)) and grid[0] else 0
        if h > 0 and w > 0:
            cx = w // 2
            cy = h // 2
            # Bias toward center if nothing else is known.
            dx = clamp_step(cx - me[0])
            dy = clamp_step(cy - me[1])
            if dx == 0 and dy == 0:
                # Small deterministic drift.
                return [1, 0]
            return [dx, dy]

    # If no objectives, move away from nearest enemy if any, else deterministic drift.
    if nearest_enemy is not None:
        return [clamp_step(me[0] - nearest_enemy[0]), clamp_step(me[1] - nearest_enemy[1])]

    return [1, 0]

